const FACES = ["U", "R", "F", "D", "L", "B"] as const;
const SUFFIXES = ["", "2", "'"];
const COLOR: Record<(typeof FACES)[number], string> = { U: "#f7f3e9", R: "#d95743", F: "#1ba77a", D: "#e7c34f", L: "#ed8e42", B: "#3b6fc7" };
const AVERAGES = [5, 12, 50, 100] as const;
const SPEED_PHASES: SplitPhase[] = ["Cross", "F2L", "OLL", "PLL"];
const DEFAULT_PHASE_TARGETS: Record<SplitPhase, number> = { Cross: 4, F2L: 12, OLL: 4, PLL: 5 };
const TARGET_PRESETS: Record<"Beginner" | "Intermediate" | "Advanced", Record<SplitPhase, number>> = {
  Beginner: { Cross: 8, F2L: 30, OLL: 10, PLL: 12 },
  Intermediate: { Cross: 4, F2L: 12, OLL: 4, PLL: 5 },
  Advanced: { Cross: 2, F2L: 7, OLL: 2, PLL: 3 },
};
type PracticeMode = "full" | "cross" | "last-layer";
type TimerDensity = "standard" | "compact";

function sameAxis(a: string, b: string) { const axis = (face: string) => (face === "U" || face === "D" ? 0 : face === "R" || face === "L" ? 1 : 2); return axis(a) === axis(b); }
function newScramble() { const moves: string[] = []; while (moves.length < 20) { const face = FACES[Math.floor(Math.random() * FACES.length)]; const previous = moves.at(-1)?.[0]; const before = moves.at(-2)?.[0]; if (face === previous || (previous && before && sameAxis(face, previous) && sameAxis(face, before))) continue; moves.push(face + SUFFIXES[Math.floor(Math.random() * SUFFIXES.length)]); } return moves.join(" "); }
function csvCell(value: string | number) { return `"${String(value).replaceAll('"', '""')}"`; }
function progressSeries(entries: SolveHistoryEntry[]) { const ordered = [...entries].reverse(); return ordered.map((_, index) => { const point: Record<string, number | null | undefined> = { solve: index + 1 }; for (const size of AVERAGES) point[`ao${size}`] = index + 1 < size ? undefined : rollingAverage(ordered.slice(index + 1 - size, index + 1)); return point; }); }
function saveFile(name: string, type: string, value: string) { const url = URL.createObjectURL(new Blob([value], { type })); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }
function canvasLines(context: CanvasRenderingContext2D, text: string, maxWidth: number) { const words = text.trim().split(/\s+/).filter(Boolean); const lines: string[] = []; let line = ""; for (const word of words) { const candidate = line ? `${line} ${word}` : word; if (line && context.measureText(candidate).width > maxWidth) { lines.push(line); line = word; } else line = candidate; } if (line) lines.push(line); return lines; }
function drawMetricCube(context: CanvasRenderingContext2D, state: string, x: number, y: number, tile: number) { const safe = state.length === 54 ? state : SOLVED_FAST_STATE; const faces = ["U", "R", "F", "D", "L", "B"] as const; const positions = { U: [1, 0], L: [0, 1], F: [1, 1], R: [2, 1], B: [3, 1], D: [1, 2] } as const; const offsets = { U: 0, R: 9, F: 18, D: 27, L: 36, B: 45 } as const; context.fillStyle = "#17221d"; context.fillRect(x - 8, y - 8, tile * 12 + 16, tile * 9 + 16); for (const face of faces) { const [column, row] = positions[face]; for (let index = 0; index < 9; index += 1) { const sticker = safe[offsets[face] + index] ?? "U"; const sx = x + (column * 3 + (index % 3)) * tile; const sy = y + (row * 3 + Math.floor(index / 3)) * tile; context.fillStyle = CUBE_COLOR[sticker] ?? "#888"; context.fillRect(sx, sy, tile - 1, tile - 1); } } }
function exportAo5Image(entries: SolveHistoryEntry[], exclusions: Record<string, "best" | "worst">, value: number | null | undefined, vi: boolean) { const width = 3200; const headerHeight = 320; const rowHeight = 330; const footerHeight = 150; const canvas = document.createElement("canvas"); canvas.width = width; canvas.height = headerHeight + entries.length * rowHeight + footerHeight; const context = canvas.getContext("2d"); if (!context) return; const margin = 100; const cubeX = 690; const scrambleX = 1120; const scrambleWidth = width - scrambleX - margin; context.fillStyle = "#f4f0e8"; context.fillRect(0, 0, canvas.width, canvas.height); context.strokeStyle = "rgba(23,34,29,.12)"; context.lineWidth = 1; for (let x = 0; x < width; x += 64) { context.beginPath(); context.moveTo(x, 0); context.lineTo(x, canvas.height); context.stroke(); } context.fillStyle = "#17221d"; context.fillRect(0, 0, width, 22); context.fillRect(margin, 62, width - margin * 2, 184); context.fillStyle = "#1ba77a"; context.font = "700 32px monospace"; context.fillText("CFOP SOLVER STUDIO · TIMER RECORD", 148, 118); context.fillStyle = "#f4f0e8"; context.font = "800 84px monospace"; context.fillText(`AO5 · ${value == null ? "DNF" : formatSolveTime(value)}`, 148, 204); context.fillStyle = "rgba(244,240,232,.72)"; context.font = "600 24px monospace"; context.fillText(vi ? "BẢNG NGANG · SCRAMBLE VÀ CUBENET TOÀN KHỔ" : "WIDE SHEET · FULL-WIDTH SCRAMBLES AND CUBENETS", 150, 236); entries.forEach((entry, index) => { const top = headerHeight + index * rowHeight; const exclusion = exclusions[entry.id]; context.fillStyle = index % 2 ? "#ebe5d9" : "#fffdfa"; context.fillRect(margin, top + 12, width - margin * 2, rowHeight - 24); context.strokeStyle = exclusion === "best" ? "#1ba77a" : exclusion === "worst" ? "#d95743" : "rgba(23,34,29,.28)"; context.lineWidth = exclusion ? 7 : 3; context.strokeRect(margin, top + 12, width - margin * 2, rowHeight - 24); context.fillStyle = exclusion === "best" ? "#176d52" : exclusion === "worst" ? "#a33d2d" : "#17221d"; context.font = "900 34px monospace"; context.fillText(String(index + 1).padStart(2, "0"), 150, top + 82); context.font = "900 58px monospace"; context.fillText(formatSolveResult(entry), 150, top + 153); context.font = "700 19px monospace"; context.fillStyle = "#65716a"; context.fillText(new Date(entry.createdAt).toLocaleDateString(vi ? "vi-VN" : "en-US"), 152, top + 196); context.fillStyle = exclusion === "best" ? "#176d52" : exclusion === "worst" ? "#a33d2d" : "#65716a"; context.font = "700 18px monospace"; context.fillText(exclusion ? (exclusion === "best" ? (vi ? "BEST · LOẠI" : "BEST · DISCARDED") : (vi ? "WORST · LOẠI" : "WORST · DISCARDED")) : (vi ? "TÍNH VÀO AO" : "COUNTED IN AO"), 150, top + 244); drawMetricCube(context, safeScrambleState(entry.input), cubeX, top + 26, 28); context.fillStyle = "#1b7b5e"; context.font = "800 20px monospace"; context.fillText("SCRAMBLE", scrambleX, top + 64); context.fillStyle = "#17221d"; context.font = "900 36px monospace"; const scramble = canvasLines(context, entry.input, scrambleWidth).slice(0, 2); scramble.forEach((line, lineIndex) => context.fillText(line, scrambleX, top + 126 + lineIndex * 50)); context.fillStyle = "#65716a"; context.font = "700 19px monospace"; context.fillText(entry.phaseSplits.length ? splitSummary(entry) : (vi ? "Không có phase split" : "No phase splits"), scrambleX, top + 245); if (entry.note) { context.font = "600 18px monospace"; context.fillText(`${vi ? "GHI CHÚ" : "NOTE"}: ${entry.note.slice(0, 132)}`, scrambleX, top + 280); } }); context.fillStyle = "#65716a"; context.font = "600 21px monospace"; context.fillText(vi ? "BEST/WORST được loại theo quy tắc Ao5 · Xuất từ CFOP Solver Studio" : "BEST/WORST are discarded under Ao5 rules · Exported from CFOP Solver Studio", margin, canvas.height - 54); const link = document.createElement("a"); link.download = `cfop-ao5-${Date.now()}.png`; link.href = canvas.toDataURL("image/png"); link.click(); }
function safeScrambleState(scramble: string) { try { return stateFromScramble(scramble); } catch { return SOLVED_FAST_STATE; } }
function initialStateFor(entry: SolveHistoryEntry) { return entry.inputKind === "state" && entry.input.length === 54 ? entry.input : stateFromScramble(entry.input); }
function splitSummary(entry: SolveHistoryEntry) { return entry.phaseSplits.map((split) => `${split.phase} ${(split.elapsedMs / 1000).toFixed(2)}s`).join(" · "); }
function readPhaseTargets(): Record<SplitPhase, number> { try { const saved = JSON.parse(localStorage.getItem("cfop-phase-targets") ?? "{}") as Partial<Record<SplitPhase, unknown>>; return Object.fromEntries(SPEED_PHASES.map((phase) => [phase, typeof saved[phase] === "number" && saved[phase] > 0 && saved[phase] < 120 ? saved[phase] : DEFAULT_PHASE_TARGETS[phase]])) as Record<SplitPhase, number>; } catch { return DEFAULT_PHASE_TARGETS; } }
function phaseProgressSeries(entries: SolveHistoryEntry[]) { return [...entries].reverse().map((entry, index) => { const point: Record<string, number | undefined> = { solve: index + 1 }; entry.phaseSplits.forEach((split) => { point[split.phase] = split.elapsedMs; }); return point; }); }
function phaseAverage(values: number[], windowSize: 5 | 12) { if (values.length < windowSize) return undefined; const sample = values.slice(0, windowSize).sort((a, b) => a - b); const core = sample.slice(1, -1); return core.reduce((sum, value) => sum + value, 0) / core.length; }
function phaseStability(entries: SolveHistoryEntry[]) { return Object.fromEntries(SPEED_PHASES.map((phase) => { const values = entries.flatMap((entry) => entry.phaseSplits.filter((split) => split.phase === phase).map((split) => split.elapsedMs)); return [phase, { count: values.length, ao5: phaseAverage(values, 5), ao12: phaseAverage(values, 12) }]; })) as Record<SplitPhase, { count: number; ao5: number | undefined; ao12: number | undefined }>; }
const MOVE_TOKEN = /(?:[URFDLBMESxyz](?:w)?(?:2|')?)/g;
function solutionMoves(solution: string) { return solution.match(MOVE_TOKEN) ?? []; }
function solutionEfficiency(entry: SolveHistoryEntry) { const moves = solutionMoves(entry.solution).length; const seconds = entry.elapsedMs / 1000; const tps = moves && seconds > 0 ? moves / seconds : 0; const label = !moves ? "—" : moves <= 45 && tps >= 3 ? "STRONG" : moves <= 60 || tps >= 2.5 ? "STEADY" : "REFINE"; return { moves, tps, label }; }
type PhaseTps = { phase: "Cross" | "F2L" | "OLL" | "PLL"; tps: number; moves: number; seconds: number };
function phaseTpsFromSolution(solution: string): PhaseTps[] {
  const buckets = new Map<PhaseTps["phase"], { moves: number; seconds: number }>();
  for (const part of solution.split(/[|;\n]+/)) {
    const match = part.trim().match(/^(Cross|F2L(?:\s*[1-4])?|OLL|PLL)\s*(?:@|:)\s*([0-9]+(?:\.[0-9]+)?)s?\s*(.*)$/i);
    if (!match) continue;
    const phase = match[1].toUpperCase().startsWith("F2L") ? "F2L" : (match[1][0].toUpperCase() + match[1].slice(1).toLowerCase()) as PhaseTps["phase"];
    const moves = (match[3].match(/(?:[URFDLBMESxyz](?:w)?(?:2|')?)/g) ?? []).length;
    const seconds = Number(match[2]);
    if (moves > 0 && seconds > 0) { const current = buckets.get(phase) ?? { moves: 0, seconds: 0 }; current.moves += moves; current.seconds += seconds; buckets.set(phase, current); }
  }
  return (["Cross", "F2L", "OLL", "PLL"] as const).flatMap((phase) => { const item = buckets.get(phase); return item ? [{ phase, ...item, tps: item.moves / item.seconds }] : []; });
}

export default function TimerLab() {
  const { language } = useLanguage();
  const vi = language === "vi";
  const [scramble, setScramble] = useState(newScramble);
  const [entries, setEntries] = useState<SolveHistoryEntry[]>(() => readSolveHistory());
  const [timerVersion, setTimerVersion] = useState(0);
  const [timerDensity, setTimerDensity] = useState<TimerDensity>(() => localStorage.getItem("cfop-timer-density") === "compact" ? "compact" : "standard");
  const [saved, setSaved] = useState(false);
  const [latestRecorded, setLatestRecorded] = useState<SolveHistoryEntry | null>(null);
  const [personalRecords, setPersonalRecords] = useState<PersonalRecord[]>([]);
  const [selectedMetric, setSelectedMetric] = useState<TimerMetricKey | null>(null);
  const [copiedScrambleId, setCopiedScrambleId] = useState<string | null>(null);
  const [showMetricCubeNets, setShowMetricCubeNets] = useState(() => localStorage.getItem("cfop-metric-cubenets") !== "off");
  const [expandedMetricCube, setExpandedMetricCube] = useState<SolveHistoryEntry | null>(null);
  const [inspectionColor, setInspectionColor] = useState<(typeof FACES)[number]>(() => { const saved = localStorage.getItem("cfop-inspection-color"); return FACES.includes(saved as (typeof FACES)[number]) ? saved as (typeof FACES)[number] : "U"; });
  const [crossHighlight, setCrossHighlight] = useState(() => localStorage.getItem("cfop-cross-highlight") !== "off");
  const [inspectionSound, setInspectionSound] = useState(() => localStorage.getItem("cfop-inspection-sound") !== "off");
  const [spaceSplits, setSpaceSplits] = useState(() => localStorage.getItem("cfop-space-splits") !== "off");
  const [phaseTargets, setPhaseTargets] = useState<Record<SplitPhase, number>>(readPhaseTargets);
  const [practiceMode, setPracticeMode] = useState<PracticeMode>("full");
  const [practiceCase, setPracticeCase] = useState<PracticeCase | null>(null);
  const [editing, setEditing] = useState<SolveHistoryEntry | null>(null);
  const [editSeconds, setEditSeconds] = useState("");
  const [editPenalty, setEditPenalty] = useState<SolvePenalty>("none");
  const [editSolution, setEditSolution] = useState("");
  const [editNote, setEditNote] = useState("");
  const [editTags, setEditTags] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<SolveHistoryEntry | null>(null);
  const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);
  const [importError, setImportError] = useState("");
  const [tagFilter, setTagFilter] = useState("all");
  const [noteQuery, setNoteQuery] = useState("");
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set());
  const [replay, setReplay] = useState<SolveHistoryEntry | null>(null);
  const [replayMode, setReplayMode] = useState<"solution" | "scramble">("solution");
  const [replayStep, setReplayStep] = useState(0);
  const [replayPlaying, setReplayPlaying] = useState(false);
  const [replaySpeed, setReplaySpeed] = useState(1);
  const [location] = useLocation();
  const labTab: "timer" | "study" = location.split("?")[0] === "/study" ? "study" : "timer";
  const [timerSettingsOpen, setTimerSettingsOpen] = useState(false);
  const [solutionError, setSolutionError] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);

  const state = useMemo(() => { try { return stateFromScramble(scramble); } catch { return SOLVED_FAST_STATE; } }, [scramble]);
  const allTags = useMemo(() => Array.from(new Set(entries.flatMap((entry) => entry.tags))).sort((a, b) => a.localeCompare(b)), [entries]);
  const visibleEntries = useMemo(() => { const needle = noteQuery.trim().toLocaleLowerCase(); return entries.filter((entry) => (tagFilter === "all" || entry.tags.includes(tagFilter)) && (!needle || entry.note.toLocaleLowerCase().includes(needle) || entry.tags.some((tag) => tag.toLocaleLowerCase().includes(needle)))); }, [entries, noteQuery, tagFilter]);
  const progress = useMemo(() => progressSeries(visibleEntries), [visibleEntries]);
  const phaseProgress = useMemo(() => phaseProgressSeries(visibleEntries.filter((entry) => entry.phaseSplits.length > 0)), [visibleEntries]);
  const phaseAo = useMemo(() => phaseStability(visibleEntries), [visibleEntries]);
  const pb = useMemo(() => { const values = visibleEntries.map(effectiveTime).filter((value): value is number => value !== null); return values.length ? Math.min(...values) : undefined; }, [visibleEntries]);
  const averages = useMemo(() => Object.fromEntries(AVERAGES.map((size) => [`ao${size}`, progress.at(-1)?.[`ao${size}`]])) as Record<`ao${typeof AVERAGES[number]}`, number | null | undefined>, [progress]);
  const selectedMetricDetail = useMemo(() => selectedMetric ? metricEvidence(visibleEntries, selectedMetric) : null, [selectedMetric, visibleEntries]);
  const latestSolution = useMemo(() => visibleEntries.find((entry) => entry.solution.trim()), [visibleEntries]);
  const latestEfficiency = useMemo(() => latestSolution ? solutionEfficiency(latestSolution) : null, [latestSolution]);
  const replayBaseState = replay ? initialStateFor(replay) : SOLVED_FAST_STATE;
  const replayText = replay?.solution ?? "";
  const replayTrace = useMemo(() => { if (!replayText.trim()) return []; try { return traceFastMoves(replayBaseState, replayText); } catch { return []; } }, [replayBaseState, replayText]);
  const replayCurrent = replayStep === 0 ? replayBaseState : replayTrace[replayStep - 1]?.state ?? SOLVED_FAST_STATE;
  const replayPrevious = replayStep > 0 ? replayTrace[replayStep - 1]?.previousState : undefined;
  const replayTps = replay && replay.elapsedMs > 0 ? replayTrace.length / (replay.elapsedMs / 1000) : 0;
  const phaseTps = useMemo(() => replay ? phaseTpsFromSolution(replay.solution) : [], [replay]);
  const allVisibleSelected = visibleEntries.length > 0 && visibleEntries.every((entry) => selectedIds.has(entry.id));

  useEffect(() => { if (!replayPlaying || replayStep >= replayTrace.length) return; const id = window.setTimeout(() => setReplayStep((value) => value + 1), Math.max(140, 560 / replaySpeed)); return () => window.clearTimeout(id); }, [replayPlaying, replayStep, replayTrace.length, replaySpeed]);
  useEffect(() => { if (replayStep >= replayTrace.length) setReplayPlaying(false); }, [replayStep, replayTrace.length]);
  useEffect(() => { localStorage.setItem("cfop-inspection-sound", inspectionSound ? "on" : "off"); }, [inspectionSound]);
  useEffect(() => { localStorage.setItem("cfop-space-splits", spaceSplits ? "on" : "off"); }, [spaceSplits]);
  useEffect(() => { localStorage.setItem("cfop-cross-highlight", crossHighlight ? "on" : "off"); }, [crossHighlight]);
  useEffect(() => { localStorage.setItem("cfop-inspection-color", inspectionColor); }, [inspectionColor]);
  useEffect(() => { localStorage.setItem("cfop-phase-targets", JSON.stringify(phaseTargets)); }, [phaseTargets]);
  useEffect(() => { localStorage.setItem("cfop-timer-density", timerDensity); }, [timerDensity]);
  useEffect(() => { localStorage.setItem("cfop-metric-cubenets", showMetricCubeNets ? "on" : "off"); }, [showMetricCubeNets]);
  useEffect(() => { document.documentElement.dataset.speedSplit = spaceSplits ? "on" : "off"; return () => { delete document.documentElement.dataset.speedSplit; }; }, [spaceSplits]);
  useEffect(() => { if (!personalRecords.length) return; const id = window.setTimeout(() => setPersonalRecords([]), 5600); return () => window.clearTimeout(id); }, [personalRecords]);

  const copy = vi ? {
    title: "Timer Lab", back: "Về Studio", inspect: "INSPECTION · PRE-SOLVE", inspectDetail: "Chọn màu Cross và quan sát cube trước khi bắt đầu solve.", scramble: "SCRAMBLE", new: "Tạo case mới", copy: "COPY", soundOn: "Âm inspection: BẬT", soundOff: "Âm inspection: TẮT", highlightOn: "Hiện Cross: BẬT", highlightOff: "Hiện Cross: TẮT", splitOn: "Split input: BẬT", splitOff: "Split input: TẮT", splitDetail: "Khi solve chạy: Space, Enter hoặc chạm timer chốt Cross → F2L → OLL → PLL.", practice: "LUYỆN RIÊNG", full: "Full solve", crossPractice: "Cross", lastLayer: "Last Layer", case: "CASE", saved: "Đã lưu lượt vào nhật ký.", stats: "THÀNH TÍCH CÁ NHÂN", progress: "TIẾN ĐỘ AVERAGE", phaseProgress: "TIẾN ĐỘ TỪNG PHA", phaseEmpty: "CẦN LƯỢT CÓ SPEED SPLIT ĐỂ VẼ BIỂU ĐỒ PHA", targets: "MỤC TIÊU PHA · GIÂY", overTarget: "VƯỢT MỤC TIÊU", history: "NHẬT KÝ LƯỢT GIẢI", exportCsv: "Xuất CSV", exportJson: "Xuất JSON", importJson: "Nhập JSON", importError: "Không thể đọc backup JSON. Hãy chọn file lịch sử hợp lệ.", empty: "CHỜ LƯỢT ĐẦU TIÊN · GIỮ VÀ THẢ SPACE / ENTER HOẶC CHẠM TIMER", emptyFilter: "KHÔNG CÓ LƯỢT KHỚP BỘ LỌC HIỆN TẠI.", edit: "Chỉnh sửa lượt", base: "THỜI GIAN GỐC", penalty: "PHẠT", none: "Không phạt", note: "GHI CHÚ", tags: "TAG (phân cách bằng dấu phẩy)", solution: "SOLUTION THỰC TẾ", solutionHint: "Ghi đúng chuỗi move bạn đã thực hiện. Hệ thống chỉ lưu khi chuỗi đưa state của scramble về solved.", save: "Lưu solution", cancel: "Hủy", remove: "Xóa", deleteTitle: "Xóa lượt giải?", deleteDetail: "Lượt này sẽ bị xóa khỏi nhật ký và thống kê.", plusTwo: "+2", dnf: "DNF", pb: "PB", total: "LƯỢT", filter: "LỌC NHẬT KÝ", allTags: "Mọi tag", noteSearch: "Tìm ghi chú hoặc tag", matched: "lượt khớp", playback: "Phát lại solution thực tế", playbackTitle: "PHÁT LẠI SOLUTION THỰC TẾ", noSolution: "Lượt này chưa có solution thực tế đã lưu.", close: "Đóng", move: "NƯỚC XOAY", restart: "Phát lại từ đầu", speed: "TỐC ĐỘ", tps: "TPS", tpsByPhase: "TPS THEO PHA", tpsEmpty: "Lưu solution kèm thời gian từng pha để xem biểu đồ TPS.", splitTimes: "THỜI GIAN PHA", selectAll: "Chọn các lượt đang lọc", selected: "đã chọn", deleteSelected: "Xóa đã chọn", deleteManyTitle: "Xóa các lượt đã chọn?", deleteManyDetail: "Các lượt đang chọn sẽ bị xóa vĩnh viễn khỏi nhật ký và thống kê.", density: "MẬT ĐỘ HIỂN THỊ", standard: "Chuẩn", compact: "Gọn", recordTitle: "KỶ LỤC MỚI", recordClose: "Đóng thông báo kỷ lục" 
  } : {
    title: "Timer Lab", back: "Back to Studio", inspect: "INSPECTION · PRE-SOLVE", inspectDetail: "Choose the Cross color and inspect the cube before the solve.", scramble: "SCRAMBLE", new: "New case", copy: "COPY", soundOn: "Inspection sound: ON", soundOff: "Inspection sound: OFF", highlightOn: "Cross view: ON", highlightOff: "Cross view: OFF", splitOn: "Space split: ON", splitOff: "Space split: OFF", splitDetail: "During a solve, Space marks Cross → F2L → OLL → PLL.", practice: "PRACTICE", full: "Full solve", crossPractice: "Cross", lastLayer: "Last Layer", case: "CASE", saved: "Solve saved to the log.", stats: "PERSONAL METRICS", progress: "FILTERED AVERAGE PROGRESS", phaseProgress: "PHASE PROGRESS", phaseEmpty: "RECORD A SPEED SPLIT TO PLOT PHASE PROGRESS", targets: "PHASE TARGETS · SECONDS", overTarget: "OVER TARGET", chartEmpty: "WAITING FOR FILTERED DATA", history: "SOLVE LOG", exportCsv: "Export CSV", exportJson: "Export JSON", importJson: "Import JSON", importError: "The JSON backup could not be read. Choose a valid history file.", empty: "No solves saved yet.", emptyFilter: "No solves match the active filter.", edit: "Edit solve", base: "BASE TIME", penalty: "PENALTY", none: "No penalty", note: "NOTE", tags: "TAGS (comma separated)", solution: "OPTIONAL SOLUTION", solutionHint: "Use the move pad below or paste notation; add phase TPS metadata only when needed.", save: "Save changes", cancel: "Cancel", remove: "Delete", deleteTitle: "Delete this solve?", deleteDetail: "This solve will be removed from the log and metrics.", plusTwo: "+2", dnf: "DNF", pb: "PB", total: "SOLVES", filter: "FILTER LOG", allTags: "All tags", noteSearch: "Search notes or tags", matched: "matching solves", playback: "Playback", playbackTitle: "SOLUTION PLAYBACK", noSolution: "No solution saved for this solve.", close: "Close", move: "MOVE", restart: "Restart playback", speed: "SPEED", tps: "TPS", tpsByPhase: "TPS BY PHASE", tpsEmpty: "Save phase timings in the solution to see the TPS chart.", splitTimes: "PHASE SPLITS", selectAll: "Select filtered solves", selected: "selected", deleteSelected: "Delete selected", deleteManyTitle: "Delete selected solves?", deleteManyDetail: "The selected solves will be permanently removed from the log and metrics.", density: "DISPLAY DENSITY", standard: "Standard", compact: "Compact", recordTitle: "NEW PERSONAL RECORD", recordClose: "Dismiss record notice"
  };
  const activeSplitDetail = practiceMode === "cross" ? (vi ? "Khi solve chạy: Space, Enter hoặc chạm timer chốt Cross và hoàn thành lượt." : "During a solve, Space, Enter, or touching the timer marks Cross and completes the attempt.") : practiceMode === "last-layer" ? (vi ? `Khi solve chạy: Space, Enter hoặc chạm timer chốt ${practiceCase?.kind ?? "Last Layer"} và hoàn thành lượt.` : `During a solve, Space, Enter, or touching the timer marks ${practiceCase?.kind ?? "Last Layer"} and completes the attempt.`) : copy.splitDetail;
  const analyticsCopy = vi ? { phaseAo: "AO5 / AO12 THEO PHA", presets: "CẤU HÌNH MỤC TIÊU", moves: "MOVES", efficiency: "HIỆU QUẢ SOLUTION", noSolution: "THÊM SOLUTION ĐỂ PHÂN TÍCH", applied: "ĐÃ ÁP DỤNG", set: "Áp dụng" } : { phaseAo: "PHASE AO5 / AO12", presets: "TARGET PRESETS", moves: "MOVES", efficiency: "SOLUTION EFFICIENCY", noSolution: "ADD A SOLUTION TO ANALYZE", applied: "APPLIED", set: "Apply" };

  const metric = (value: number | null | undefined) => value === undefined ? "--:--" : value === null ? "DNF" : formatSolveTime(value);
  const metricLabel = (key: TimerMetricKey) => key === "pb" ? copy.pb : key === "total" ? copy.total : key.toUpperCase();
  const copyMetricScramble = (entry: SolveHistoryEntry) => { const complete = () => { setCopiedScrambleId(entry.id); window.setTimeout(() => setCopiedScrambleId((current) => current === entry.id ? null : current), 1800); }; if (navigator.clipboard?.writeText) { void navigator.clipboard.writeText(entry.input).then(complete).catch(() => undefined); return; } const fallback = document.createElement("textarea"); fallback.value = entry.input; document.body.appendChild(fallback); fallback.select(); document.execCommand("copy"); fallback.remove(); complete(); };
  const recordLabel = (record: PersonalRecord) => record.key === "single" ? "PB SINGLE" : record.key.toUpperCase();
  const nextScramble = (mode = practiceMode, clearSaved = true) => { if (mode === "last-layer") { const cases = [...OLL_CASES, ...PLL_CASES]; const nextCase = cases[Math.floor(Math.random() * cases.length)]; setPracticeCase(nextCase); setScramble(nextCase.setup); } else { setPracticeCase(null); setScramble(newScramble()); } if (clearSaved) setSaved(false); setTimerVersion((value) => value + 1); };
  const selectPracticeMode = (mode: PracticeMode) => { setPracticeMode(mode); nextScramble(mode); };
  const practiceSplitPhases: readonly SplitPhase[] = practiceMode === "cross" ? ["Cross"] : practiceMode === "last-layer" ? [practiceCase?.kind ?? "OLL"] : SPEED_PHASES;
  const recordSolve = (completion: TimerCompletion) => { const tags = practiceMode === "full" ? [] : [practiceMode === "cross" ? "practice:cross" : "practice:last-layer", ...(practiceCase ? [`case:${practiceCase.kind}-${practiceCase.id}`] : [])]; const item = addSolveHistory({ elapsedMs: completion.elapsedMs, inspectionMs: completion.inspectionMs, penalty: completion.automaticPenalty, phaseSplits: completion.phaseSplits, input: scramble, inputKind: "scramble", moves: 0, tags }); setPersonalRecords(detectPersonalRecords(entries, item)); setEntries((previous) => [item, ...previous].slice(0, 500)); setLatestRecorded(item); setSaved(true); nextScramble(practiceMode, false); };
  const openEdit = (entry: SolveHistoryEntry) => { setEditing(entry); setEditSeconds((entry.elapsedMs / 1000).toFixed(2)); setEditPenalty(entry.penalty); setEditSolution(entry.solution); setEditNote(entry.note); setEditTags(entry.tags.join(", ")); setSolutionError(""); };
  const saveEdit = () => { if (!editing) return; const seconds = Number(editSeconds); if (!Number.isFinite(seconds) || seconds < 0) return; const validation = validateRecordedSolution(initialStateFor(editing), editSolution); if (!validation.valid && validation.error !== "empty") { setSolutionError(validation.error === "unfinished" ? (vi ? "Chuỗi move chưa đưa cube về trạng thái solved. Kiểm tra lại solution thực tế." : "This move sequence does not return the cube to solved. Check the recorded solution.") : (vi ? "Solution có notation không được hỗ trợ. Dùng các move Cube 3×3 chuẩn." : "The solution contains unsupported notation. Use standard 3×3 moves.")); return; } setEntries(updateSolveHistory(editing.id, { elapsedMs: Math.round(seconds * 1000), penalty: editPenalty, solution: validation.normalized, moves: validation.moves.length, note: editNote.trim(), tags: editTags.split(",").map((tag) => tag.trim()).filter(Boolean) })); setSolutionError(""); setEditing(null); };
  const applyPenalty = (entry: SolveHistoryEntry, penalty: SolvePenalty) => setEntries(updateSolveHistory(entry.id, { penalty: entry.penalty === penalty ? "none" : penalty }));
  const toggleSelection = (id: string) => setSelectedIds((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const selectVisible = () => setSelectedIds((current) => { const next = new Set(current); if (allVisibleSelected) visibleEntries.forEach((entry) => next.delete(entry.id)); else visibleEntries.forEach((entry) => next.add(entry.id)); return next; });
  const deleteSelected = () => { setEntries(deleteSolveHistoryMany(selectedIds)); setSelectedIds(new Set()); setBulkDeleteOpen(false); };
  const exportCsv = () => saveFile("cfop-timer-history.csv", "text/csv;charset=utf-8", [["timestamp", "base_time_ms", "inspection_ms", "penalty", "result", "phase_splits", "scramble", "solution", "notes", "tags"], ...entries.map((item) => [new Date(item.createdAt).toISOString(), item.elapsedMs, item.inspectionMs, item.penalty, formatSolveResult(item), splitSummary(item), item.input, item.solution, item.note, item.tags.join("|")])].map((row) => row.map(csvCell).join(",")).join("\n"));
  const exportJson = () => saveFile("cfop-timer-backup.json", "application/json", JSON.stringify(exportSolveHistory(), null, 2));
  const onImport = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { setEntries(importSolveHistory(JSON.parse(await file.text()))); setSelectedIds(new Set()); setImportError(""); } catch { setImportError(copy.importError); } finally { event.target.value = ""; } };
  const openReplay = (entry: SolveHistoryEntry) => { const validation = validateRecordedSolution(initialStateFor(entry), entry.solution); if (!validation.valid || !validation.moves.length) return; setReplayMode("solution"); setReplay({ ...entry, solution: validation.normalized }); setReplayStep(0); setReplayPlaying(false); setReplaySpeed(1); };
  const openScrambleReplay = (entry: SolveHistoryEntry) => openReplay(entry);

  return <main className={`timer-lab bs-page timer-density-${timerDensity} history-surface min-vh-100 py-4`}><div className="container-xxl pb-5">
    {labTab === "study" ? <LastLayerStudyLab language={language} /> : <>
    <section className="timer-lab-stack">
      <section className="timer-competition-apparatus history-panel border-2 border-[#17221d] bg-white p-5 sm:p-7"><div className="tick-ruler tick-ruler-ink" />
        <p className="timer-scramble break-words font-mono text-xl font-bold leading-8 tracking-[0.04em] text-[#17221d] sm:text-2xl">{scramble}</p><div className="timer-scramble-actions mt-2 flex items-center gap-1"><button onClick={() => nextScramble()} title={copy.new} aria-label={copy.new}><Dices className="h-3.5 w-3.5" /></button><button onClick={() => navigator.clipboard?.writeText(scramble)} title={copy.copy} aria-label={copy.copy}><ClipboardCheck className="h-3.5 w-3.5" /></button><button onClick={() => setTimerSettingsOpen(true)} title={vi ? "Cài đặt Timer" : "Timer settings"} aria-label={vi ? "Cài đặt Timer" : "Timer settings"}><Settings2 className="h-3.5 w-3.5" /></button></div>
        <div className="timer-device-grid mt-6"><div className="min-w-0"><SolveTimer key={timerVersion} onComplete={recordSolve} soundEnabled={inspectionSound} splitEnabled={spaceSplits || practiceMode !== "full"} splitPhases={practiceSplitPhases} />{(spaceSplits || practiceMode !== "full") && <p className="mt-3 font-mono text-[9px] font-bold uppercase tracking-[0.1em] text-[#f4f0e8]/60">{activeSplitDetail}</p>}{saved && <p className="mt-3 font-mono text-[10px] font-bold uppercase tracking-[0.14em] text-[#64d4ad]">✓ {copy.saved}</p>}{saved && latestRecorded && !latestRecorded.solution.trim() && <div className="timer-solution-capture mt-3"><div><p>{vi ? "GHI SOLUTION THỰC TẾ" : "RECORD ACTUAL SOLUTION"}</p><span>{vi ? "Timer không thể tự biết các nước bạn đã xoay; hãy nhập hoặc dán chuỗi move để phát lại chính xác." : "The timer cannot observe physical turns; enter or paste your move sequence for an exact replay."}</span></div><button type="button" onClick={() => openEdit(latestRecorded)}>{vi ? "NHẬP SOLUTION" : "ADD SOLUTION"}</button></div>}</div><div className="timer-device-cube"><Cube3DGuide state={state} step={0} crossColor={inspectionColor} inspection alignCross highlightCross={crossHighlight} /></div></div>
        <details className="timer-setup-sheet mt-6 border-y border-[#17221d]/14 py-3"><summary className="cursor-pointer font-mono text-[10px] font-bold tracking-[0.12em] text-[#17221d]/60">{vi ? "THIẾT LẬP INSPECTION · LUYỆN TẬP" : "INSPECTION · PRACTICE SETUP"}</summary><div className="mt-4 grid gap-4 lg:grid-cols-[1fr_auto]"><div className="space-y-4"><div><p className="font-mono text-[9px] font-bold tracking-[0.12em] text-[#17221d]/55">{copy.practice}</p><div className="mt-2 flex flex-wrap gap-1"><button onClick={() => selectPracticeMode("full")} className={`rounded-sm border px-2 py-1 font-mono text-[9px] font-bold ${practiceMode === "full" ? "border-[#17221d] bg-[#17221d] text-[#f4f0e8]" : "border-[#17221d]/20 bg-white"}`}>{copy.full}</button><button onClick={() => selectPracticeMode("cross")} className={`rounded-sm border px-2 py-1 font-mono text-[9px] font-bold ${practiceMode === "cross" ? "border-[#1ba77a] bg-[#1ba77a] text-[#17221d]" : "border-[#17221d]/20 bg-white"}`}>{copy.crossPractice}</button><button onClick={() => selectPracticeMode("last-layer")} className={`rounded-sm border px-2 py-1 font-mono text-[9px] font-bold ${practiceMode === "last-layer" ? "border-[#1ba77a] bg-[#1ba77a] text-[#17221d]" : "border-[#17221d]/20 bg-white"}`}>{copy.lastLayer}</button></div>{practiceCase && <p className="mt-2 font-mono text-[10px] font-bold text-[#1b7b5e]">{copy.case} · {practiceCase.kind} {practiceCase.id} · {practiceCase.group}</p>}</div><div className="flex flex-wrap gap-2"><button onClick={() => setCrossHighlight((value) => !value)} className={`rounded-sm border px-2 py-1 font-mono text-[9px] font-bold ${crossHighlight ? "border-[#1ba77a] bg-[#1ba77a] text-[#17221d]" : "border-[#17221d]/30 bg-white text-[#17221d]"}`}>{crossHighlight ? copy.highlightOn : copy.highlightOff}</button><button onClick={() => setSpaceSplits((value) => !value)} className={`rounded-sm border px-2 py-1 font-mono text-[9px] font-bold ${spaceSplits ? "border-[#1ba77a] bg-[#1ba77a] text-[#17221d]" : "border-[#17221d]/30 bg-white text-[#17221d]"}`}>{spaceSplits ? copy.splitOn : copy.splitOff}</button><button onClick={() => setInspectionSound((value) => !value)} className="rounded-sm border border-[#17221d]/30 bg-white px-2 py-1 font-mono text-[9px] font-bold text-[#17221d]">{inspectionSound ? copy.soundOn : copy.soundOff}</button></div></div><div><p className="font-mono text-[9px] font-bold tracking-[0.12em] text-[#17221d]/55">{vi ? "MÀU CROSS" : "CROSS COLOR"}</p><div className="mt-2 flex gap-1" role="radiogroup" aria-label="Cross color">{FACES.map((face) => <button key={face} role="radio" aria-checked={inspectionColor === face} onClick={() => setInspectionColor(face)} className={`grid h-8 w-8 place-items-center rounded-sm border-2 ${inspectionColor === face ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}><span className="h-3.5 w-3.5 rounded-sm border border-black/30" style={{ backgroundColor: COLOR[face] }} /></button>)}</div></div></div></details>
      </section>
      <aside className="timer-visible-metrics history-panel border-2 border-[#17221d] bg-[#e9e3d6] p-4" aria-label={copy.stats}><div className="tick-ruler tick-ruler-ink" /><div className="flex items-center justify-between gap-3"><p className="font-mono text-[10px] font-bold uppercase tracking-[0.16em] text-[#1ba77a]">{copy.stats}</p><span className="font-mono text-[9px] font-bold text-[#17221d]/45">{visibleEntries.length} {copy.total}</span></div><div className="mt-3 grid grid-cols-2 gap-2"><MetricButton label={copy.pb} value={metric(pb)} enabled={pb !== undefined} onClick={() => setSelectedMetric("pb")} /><MetricButton label="AO5" value={metric(averages.ao5)} enabled={averages.ao5 !== undefined} onClick={() => setSelectedMetric("ao5")} /><MetricButton label="AO12" value={metric(averages.ao12)} enabled={averages.ao12 !== undefined} onClick={() => setSelectedMetric("ao12")} /><MetricButton label="AO50" value={metric(averages.ao50)} enabled={averages.ao50 !== undefined} onClick={() => setSelectedMetric("ao50")} /><MetricButton label="AO100" value={metric(averages.ao100)} enabled={averages.ao100 !== undefined} onClick={() => setSelectedMetric("ao100")} /><MetricButton label={copy.total} value={String(visibleEntries.length)} enabled={visibleEntries.length > 0} onClick={() => setSelectedMetric("total")} /></div></aside>
      {personalRecords.length > 0 && <aside className="timer-record-celebration" role="status" aria-live="polite"><div className="timer-record-spark" aria-hidden="true" /><div className="timer-record-copy"><span className="timer-record-mark"><Trophy className="h-4 w-4" /></span><div><p>{copy.recordTitle}</p><div className="timer-record-values">{personalRecords.map((record) => <span key={record.key}><b>{recordLabel(record)}</b> {formatSolveTime(record.value)}</span>)}</div></div></div><button type="button" onClick={() => setPersonalRecords([])} aria-label={copy.recordClose}><X className="h-3.5 w-3.5" /></button></aside>}

      <details className="timer-secondary-sheet timer-analytics-sheet mt-7 border-2 border-[#17221d]/30 bg-[#f8f5ed] p-4"><summary className="cursor-pointer font-mono text-[10px] font-bold tracking-[0.14em] text-[#17221d]/65">{vi ? "MỞ PHÂN TÍCH & MỤC TIÊU" : "OPEN ANALYTICS & TARGETS"}</summary><div className="mt-5 space-y-7"><section className="metrics-panel grid gap-7 xl:grid-cols-[340px_minmax(0,1fr)]"><div className="history-panel border-2 border-[#17221d] bg-[#e9e3d6] p-5"><div className="tick-ruler tick-ruler-ink" /><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{copy.stats}</p><div className="mt-4 grid grid-cols-3 gap-2"><Metric label={copy.pb} value={metric(pb)} /><Metric label="AO5" value={metric(averages.ao5)} /><Metric label="AO12" value={metric(averages.ao12)} /><Metric label="AO50" value={metric(averages.ao50)} /><Metric label="AO100" value={metric(averages.ao100)} /><Metric label={copy.total} value={String(visibleEntries.length)} /></div></div><div className="history-panel border-2 border-[#17221d] bg-white p-5"><div className="tick-ruler tick-ruler-ink" /><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{copy.progress}</p>{visibleEntries.length ? <div className="mt-4 h-72"><ResponsiveContainer width="100%" height="100%"><LineChart data={progress}><XAxis dataKey="solve" type="number" axisLine={false} tickLine={false} /><YAxis tickFormatter={(value) => `${(Number(value) / 1000).toFixed(0)}s`} axisLine={false} tickLine={false} width={46} /><Tooltip formatter={(value) => [value == null ? "DNF" : `${(Number(value) / 1000).toFixed(2)}s`]} /><Line type="monotone" dataKey="ao5" stroke="#1ba77a" strokeWidth={3} dot={false} connectNulls name="Ao5" /><Line type="monotone" dataKey="ao12" stroke="#17221d" strokeWidth={2} dot={false} connectNulls name="Ao12" /><Line type="monotone" dataKey="ao50" stroke="#d95743" strokeWidth={2} strokeDasharray="5 3" dot={false} connectNulls name="Ao50" /><Line type="monotone" dataKey="ao100" stroke="#3b6fc7" strokeWidth={2} strokeDasharray="2 4" dot={false} connectNulls name="Ao100" /></LineChart></ResponsiveContainer></div> : <div className="mt-4 grid h-72 place-items-center border-2 border-dashed border-[#17221d]/20 bg-[#f4f0e8] p-5 text-center"><b className="font-mono text-2xl tracking-[-0.08em]">AO5 / AO12 / AO50 / AO100</b><p className="mt-3 font-mono text-[10px] leading-5 tracking-[0.08em] text-[#17221d]/60">{copy.chartEmpty}</p></div>}</div></section>

      <section className="mt-7 grid gap-7 xl:grid-cols-[340px_minmax(0,1fr)]"><div className="history-panel border-2 border-[#17221d] bg-[#e9e3d6] p-5"><div className="tick-ruler tick-ruler-ink" /><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{copy.targets}</p><div className="mt-4 space-y-3">{SPEED_PHASES.map((phase) => <label key={phase} className="flex items-center justify-between gap-3 border-b border-[#17221d]/10 pb-2 font-mono text-xs font-bold"><span>{phase}</span><span className="flex items-center gap-1"><input type="number" min="0.1" max="120" step="0.1" value={phaseTargets[phase]} onChange={(event) => { const next = Number(event.target.value); if (Number.isFinite(next) && next > 0) setPhaseTargets((current) => ({ ...current, [phase]: next })); }} className="w-16 border-b-2 border-[#17221d]/25 bg-transparent py-1 text-right outline-none focus:border-[#1ba77a]" /><span className="text-[#17221d]/45">s</span></span></label>)}</div></div><div className="history-panel border-2 border-[#17221d] bg-white p-5"><div className="tick-ruler tick-ruler-ink" /><div className="flex items-center justify-between gap-3"><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{copy.phaseProgress}</p><span className="font-mono text-[9px] text-[#17221d]/50">{phaseProgress.length} {copy.matched}</span></div>{phaseProgress.length ? <div className="mt-4 h-72"><ResponsiveContainer width="100%" height="100%"><LineChart data={phaseProgress}><XAxis dataKey="solve" axisLine={false} tickLine={false} /><YAxis tickFormatter={(value) => `${Number(value).toFixed(0)}s`} axisLine={false} tickLine={false} width={42} /><Tooltip formatter={(value) => [`${(Number(value) / 1000).toFixed(2)}s`, ""]} /><Line type="monotone" dataKey="Cross" stroke="#1ba77a" strokeWidth={3} dot={{ r: 2 }} connectNulls /><Line type="monotone" dataKey="F2L" stroke="#ed8e42" strokeWidth={2} dot={{ r: 2 }} connectNulls /><Line type="monotone" dataKey="OLL" stroke="#3b6fc7" strokeWidth={2} dot={{ r: 2 }} connectNulls /><Line type="monotone" dataKey="PLL" stroke="#d95743" strokeWidth={2} dot={{ r: 2 }} connectNulls /></LineChart></ResponsiveContainer></div> : <div className="mt-4 grid h-72 place-items-center border-2 border-dashed border-[#17221d]/20 bg-[#f4f0e8] p-5 text-center"><p className="font-mono text-[10px] leading-5 tracking-[0.08em] text-[#17221d]/60">{copy.phaseEmpty}</p></div>}</div></section>

      <section className="mt-7 grid gap-7 xl:grid-cols-[340px_minmax(0,1fr)]"><div className="history-panel border-2 border-[#17221d] bg-[#e9e3d6] p-5"><div className="tick-ruler tick-ruler-ink" /><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{analyticsCopy.presets}</p><div className="mt-4 space-y-2">{(Object.entries(TARGET_PRESETS) as [keyof typeof TARGET_PRESETS, Record<SplitPhase, number>][]).map(([name, targets]) => { const active = SPEED_PHASES.every((phase) => phaseTargets[phase] === targets[phase]); return <button key={name} onClick={() => setPhaseTargets({ ...targets })} className={`flex w-full items-center justify-between border-2 px-3 py-2 text-left transition ${active ? "border-[#17221d] bg-[#1ba77a] text-[#17221d]" : "border-[#17221d]/15 bg-white hover:border-[#17221d]"}`}><span className="font-mono text-xs font-bold">{name}</span><span className="font-mono text-[9px]">{active ? analyticsCopy.applied : analyticsCopy.set}</span></button>; })}</div></div><div className="history-panel border-2 border-[#17221d] bg-white p-5"><div className="tick-ruler tick-ruler-ink" /><div className="flex items-center justify-between gap-3"><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{analyticsCopy.phaseAo}</p><span className="font-mono text-[9px] text-[#17221d]/45">{visibleEntries.length} {copy.matched}</span></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{SPEED_PHASES.map((phase) => <div key={phase} className="border-2 border-[#17221d]/15 bg-[#f4f0e8] p-3"><div className="flex items-center justify-between"><b className="font-mono text-xs">{phase}</b><span className="font-mono text-[9px] text-[#17221d]/50">{phaseAo[phase].count}</span></div><div className="mt-3 grid grid-cols-2 gap-2 font-mono"><div><p className="text-[8px] font-bold text-[#17221d]/45">AO5</p><p className="mt-1 text-sm font-black">{phaseAo[phase].ao5 === undefined ? "—" : formatSolveTime(phaseAo[phase].ao5)}</p></div><div><p className="text-[8px] font-bold text-[#17221d]/45">AO12</p><p className="mt-1 text-sm font-black">{phaseAo[phase].ao12 === undefined ? "—" : formatSolveTime(phaseAo[phase].ao12)}</p></div></div></div>)}</div></div></section>

      <section className="history-panel mt-7 border-2 border-[#17221d] bg-[#17221d] p-5 text-[#f4f0e8]"><div className="tick-ruler" /><div className="flex flex-wrap items-center justify-between gap-3"><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{analyticsCopy.efficiency}</p>{latestSolution && <span className="font-mono text-[9px] text-[#f4f0e8]/55">{new Date(latestSolution.createdAt).toLocaleDateString(vi ? "vi-VN" : "en-US")}</span>}</div>{latestEfficiency ? <div className="mt-4 grid grid-cols-3 gap-2"><MetricDark label={analyticsCopy.moves} value={String(latestEfficiency.moves)} /><MetricDark label={copy.tps} value={latestEfficiency.tps.toFixed(2)} /><MetricDark label="RATING" value={latestEfficiency.label} /></div> : <p className="mt-4 border-2 border-dashed border-white/20 p-4 font-mono text-[10px] tracking-[0.08em] text-[#f4f0e8]/60">{analyticsCopy.noSolution}</p>}</section>

      </div></details>
      <section className="history-panel mt-7 border-2 border-[#17221d] bg-white p-5"><div className="tick-ruler tick-ruler-ink" /><div className="flex flex-wrap items-center justify-between gap-3"><p className="font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-[#1ba77a]">{copy.history}</p><div className="flex flex-wrap gap-2"><input ref={fileRef} onChange={onImport} accept="application/json,.json" type="file" className="hidden" /><button onClick={() => fileRef.current?.click()} className="scanner-button scanner-secondary"><FileUp className="h-4 w-4" />{copy.importJson}</button><button disabled={!entries.length} onClick={exportJson} className="scanner-button scanner-secondary disabled:opacity-40"><FileDown className="h-4 w-4" />{copy.exportJson}</button><button disabled={!entries.length} onClick={exportCsv} className="scanner-button scanner-secondary disabled:opacity-40"><Download className="h-4 w-4" />{copy.exportCsv}</button></div></div>{importError && <p className="mt-3 border border-[#d95743] bg-[#d95743]/10 p-3 text-sm text-[#8b2d21]">{importError}</p>}
        <div className="mt-4 grid gap-3 border-y-2 border-[#17221d]/10 bg-[#f4f0e8] p-3 lg:grid-cols-[auto_minmax(0,1fr)_auto]"><div><p className="font-mono text-[9px] font-bold tracking-[0.14em] text-[#17221d]/55">{copy.filter}</p><div className="mt-2 flex max-w-full flex-wrap gap-1">{["all", ...allTags].map((tag) => <button key={tag} onClick={() => setTagFilter(tag)} className={`rounded-sm border px-2 py-1 font-mono text-[10px] ${tagFilter === tag ? "border-[#17221d] bg-[#1ba77a] text-[#17221d]" : "border-[#17221d]/15 bg-white"}`}>{tag === "all" ? copy.allTags : tag}</button>)}</div></div><label className="relative min-w-0 self-end"><Search className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-[#17221d]/40" /><input value={noteQuery} onChange={(event) => setNoteQuery(event.target.value)} placeholder={copy.noteSearch} className="w-full rounded-sm border-2 border-[#17221d]/20 bg-white py-2 pl-9 pr-3 font-mono text-xs outline-none focus:border-[#1ba77a]" /></label><p className="self-end whitespace-nowrap font-mono text-[10px] font-bold text-[#1b7b5e]">{visibleEntries.length} {copy.matched}</p></div>
        {visibleEntries.length > 0 && <div className="mt-3 flex flex-wrap items-center justify-between gap-3 border-b border-[#17221d]/10 pb-3"><label className="flex cursor-pointer items-center gap-2 font-mono text-[10px] font-bold uppercase tracking-[0.1em]"><input type="checkbox" checked={allVisibleSelected} onChange={selectVisible} className="h-4 w-4 accent-[#1ba77a]" />{copy.selectAll}</label><div className="flex items-center gap-3"><span className="font-mono text-[10px] text-[#17221d]/60">{selectedIds.size} {copy.selected}</span><button disabled={!selectedIds.size} onClick={() => setBulkDeleteOpen(true)} className="scanner-button scanner-secondary border-[#d95743]/40 text-[#b23b2b] disabled:opacity-35"><Trash2 className="h-4 w-4" />{copy.deleteSelected}</button></div></div>}
        {entries.length ? visibleEntries.length ? <div className="mt-1 divide-y divide-[#17221d]/10">{visibleEntries.slice(0, 24).map((item) => <div key={item.id} className="grid gap-3 py-4 lg:grid-cols-[auto_minmax(0,1fr)_auto_auto]"><label className="flex items-start pt-1"><input type="checkbox" checked={selectedIds.has(item.id)} onChange={() => toggleSelection(item.id)} className="h-4 w-4 accent-[#1ba77a]" aria-label={`Select ${item.id}`} /></label><div><p className="font-mono text-xs font-bold">{item.input}</p><p className="mt-1 font-mono text-[10px] text-[#17221d]/55">{new Date(item.createdAt).toLocaleString(vi ? "vi-VN" : "en-US")} · {item.moves} {vi ? "nước" : "moves"}{item.inspectionMs > 0 ? ` · ${copy.inspect} ${(item.inspectionMs / 1000).toFixed(2)}s` : ""}</p>{item.phaseSplits.length > 0 && <div className="mt-2 flex flex-wrap gap-1.5">{item.phaseSplits.map((split) => { const over = split.elapsedMs > phaseTargets[split.phase] * 1000; return <span key={split.phase} className={`rounded-sm border px-1.5 py-0.5 font-mono text-[9px] font-bold ${over ? "border-[#d95743] bg-[#d95743]/10 text-[#8b2d21]" : "border-[#1ba77a]/40 bg-[#1ba77a]/10 text-[#1b7b5e]"}`}>{split.phase} {(split.elapsedMs / 1000).toFixed(2)}s{over ? ` · ${copy.overTarget}` : ""}</span>; })}</div>}{item.tags.length > 0 && <div className="mt-2 flex flex-wrap gap-1">{item.tags.map((tag) => <span key={tag} className="inline-flex items-center gap-1 rounded-sm border border-[#1ba77a]/40 bg-[#1ba77a]/10 px-1.5 py-0.5 font-mono text-[9px]"><Tag className="h-2.5 w-2.5" />{tag}</span>)}</div>}{item.note && <p className="mt-2 max-w-2xl text-xs italic text-[#17221d]/65">{item.note}</p>}</div><div className="flex flex-wrap items-center gap-1"><button onClick={() => applyPenalty(item, "+2")} className={`rounded-sm border px-2 py-1 font-mono text-[10px] ${item.penalty === "+2" ? "border-[#d95743] bg-[#d95743]/15 text-[#8b2d21]" : "border-[#17221d]/15"}`}>{copy.plusTwo}</button><button onClick={() => applyPenalty(item, "DNF")} className={`rounded-sm border px-2 py-1 font-mono text-[10px] ${item.penalty === "DNF" ? "border-[#d95743] bg-[#d95743]/15 text-[#8b2d21]" : "border-[#17221d]/15"}`}>{copy.dnf}</button><button disabled={!item.solution.trim()} onClick={() => openReplay(item)} className="rounded-sm border border-[#17221d]/15 p-1.5 disabled:cursor-not-allowed disabled:opacity-30" aria-label={copy.playback}><Play className="h-3.5 w-3.5 fill-current" /></button><button onClick={() => openEdit(item)} className="rounded-sm border border-[#17221d]/15 p-1.5" aria-label={copy.edit}><Pencil className="h-3.5 w-3.5" /></button><button onClick={() => setDeleteTarget(item)} className="rounded-sm border border-[#d95743]/30 p-1.5 text-[#b23b2b]" aria-label={copy.remove}><Trash2 className="h-3.5 w-3.5" /></button></div><b className={`font-mono text-lg ${item.penalty === "DNF" ? "text-[#b23b2b]" : ""}`}>{formatSolveResult(item)}</b></div>)}</div> : <p className="mt-4 border-2 border-dashed border-[#17221d]/20 bg-[#f4f0e8] p-4 text-sm text-[#17221d]/60">{copy.emptyFilter}</p> : <p className="mt-4 border-2 border-dashed border-[#17221d]/20 bg-[#f4f0e8] p-4 text-sm text-[#17221d]/60">{copy.empty}</p>}
      </section>
    </section>

    <Sheet open={timerSettingsOpen} onOpenChange={setTimerSettingsOpen}><SheetContent side="right" className="timer-settings-panel overflow-y-auto border-l-2 border-[#17221d] bg-[#f4f0e8] p-0 text-[#17221d]"><SheetHeader className="border-b-2 border-[#17221d] bg-[#17221d] p-5 text-[#f4f0e8]"><SheetTitle className="font-mono text-sm font-bold tracking-[0.14em] text-[#1ba77a]">{vi ? "CÀI ĐẶT TIMER" : "TIMER SETTINGS"}</SheetTitle><SheetDescription className="font-mono text-[10px] leading-5 text-[#f4f0e8]/65">{vi ? "Inspection, luyện tập, màu Cross, mật độ hiển thị và mục tiêu pha." : "Inspection, practice, Cross color, density, and phase targets."}</SheetDescription></SheetHeader><div className="space-y-7 p-5"><section><p className="font-mono text-[10px] font-bold tracking-[0.14em] text-[#1b7b5e]">{copy.density}</p><div className="mt-3 grid grid-cols-2 gap-2"><button type="button" aria-pressed={timerDensity === "standard"} onClick={() => setTimerDensity("standard")} className={`border-2 px-3 py-3 text-left font-mono text-[10px] font-bold ${timerDensity === "standard" ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}><span className="block">{copy.standard}</span><span className="mt-1 block font-normal text-[#17221d]/55">{vi ? "Giữ khoảng thở" : "More breathing room"}</span></button><button type="button" aria-pressed={timerDensity === "compact"} onClick={() => setTimerDensity("compact")} className={`border-2 px-3 py-3 text-left font-mono text-[10px] font-bold ${timerDensity === "compact" ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}><span className="block">{copy.compact}</span><span className="mt-1 block font-normal text-[#17221d]/55">{vi ? "Tối ưu màn hình" : "Save screen space"}</span></button></div></section><section><p className="font-mono text-[10px] font-bold tracking-[0.14em] text-[#1b7b5e]">{vi ? "INSPECTION & INPUT" : "INSPECTION & INPUT"}</p><div className="mt-3 grid gap-2"><button onClick={() => setCrossHighlight((value) => !value)} className={`flex items-center justify-between border-2 px-3 py-2 font-mono text-[10px] font-bold ${crossHighlight ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}><span>{vi ? "HIGHLIGHT CROSS" : "CROSS HIGHLIGHT"}</span><b>{crossHighlight ? "ON" : "OFF"}</b></button><button onClick={() => setSpaceSplits((value) => !value)} className={`flex items-center justify-between border-2 px-3 py-2 font-mono text-[10px] font-bold ${spaceSplits ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}><span>{vi ? "SPLIT INPUT" : "INPUT SPLITS"}</span><b>{spaceSplits ? "ON" : "OFF"}</b></button><button onClick={() => setInspectionSound((value) => !value)} className={`flex items-center justify-between border-2 px-3 py-2 font-mono text-[10px] font-bold ${inspectionSound ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}><span>{vi ? "ÂM INSPECTION" : "INSPECTION SOUND"}</span><b>{inspectionSound ? "ON" : "OFF"}</b></button></div></section><section><p className="font-mono text-[10px] font-bold tracking-[0.14em] text-[#1b7b5e]">{vi ? "MÀU CROSS" : "CROSS COLOR"}</p><div className="mt-3 grid grid-cols-6 gap-2" role="radiogroup" aria-label="Cross color">{FACES.map((face) => <button key={face} role="radio" aria-checked={inspectionColor === face} onClick={() => setInspectionColor(face)} className={`grid aspect-square place-items-center border-2 ${inspectionColor === face ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}><span className="h-5 w-5 border border-black/30" style={{ backgroundColor: COLOR[face] }} /></button>)}</div></section><section><p className="font-mono text-[10px] font-bold tracking-[0.14em] text-[#1b7b5e]">{copy.practice}</p><div className="mt-3 grid grid-cols-3 gap-2"><button onClick={() => selectPracticeMode("full")} className={`border-2 px-2 py-2 font-mono text-[10px] font-bold ${practiceMode === "full" ? "border-[#17221d] bg-[#17221d] text-[#f4f0e8]" : "border-[#17221d]/20 bg-white"}`}>{copy.full}</button><button onClick={() => selectPracticeMode("cross")} className={`border-2 px-2 py-2 font-mono text-[10px] font-bold ${practiceMode === "cross" ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}>{copy.crossPractice}</button><button onClick={() => selectPracticeMode("last-layer")} className={`border-2 px-2 py-2 font-mono text-[10px] font-bold ${practiceMode === "last-layer" ? "border-[#17221d] bg-[#1ba77a]" : "border-[#17221d]/20 bg-white"}`}>{copy.lastLayer}</button></div></section><section><p className="font-mono text-[10px] font-bold tracking-[0.14em] text-[#1b7b5e]">{copy.targets}</p><div className="mt-3 space-y-2">{SPEED_PHASES.map((phase) => <label key={phase} className="flex items-center justify-between border-b border-[#17221d]/12 pb-2 font-mono text-xs font-bold"><span>{phase}</span><span className="flex items-center gap-1"><input type="number" min="0.1" max="120" step="0.1" value={phaseTargets[phase]} onChange={(event) => { const next = Number(event.target.value); if (Number.isFinite(next) && next > 0) setPhaseTargets((current) => ({ ...current, [phase]: next })); }} className="w-16 border-b-2 border-[#17221d]/25 bg-transparent py-1 text-right outline-none focus:border-[#1ba77a]" /><span className="text-[#17221d]/45">s</span></span></label>)}</div></section></div></SheetContent></Sheet>
    <Dialog open={Boolean(selectedMetric)} onOpenChange={(open) => !open && setSelectedMetric(null)}><DialogContent className="metric-detail-dialog max-h-[90vh] overflow-y-auto border-2 border-[#17221d] bg-[#f4f0e8] text-[#17221d]"><DialogHeader><DialogTitle className="font-mono text-sm tracking-[0.14em]">{vi ? "CHI TIẾT THÀNH TÍCH" : "METRIC DETAIL"} · {selectedMetric ? metricLabel(selectedMetric) : "—"}</DialogTitle><DialogDescription className="font-mono text-xs">{selectedMetricDetail?.value === undefined ? (vi ? "Chưa đủ lượt hợp lệ để tạo chỉ số này." : "Not enough valid solves to form this metric.") : selectedMetric === "total" ? `${selectedMetricDetail.entries.length} ${copy.total.toLowerCase()}` : metric(selectedMetricDetail?.value)}</DialogDescription></DialogHeader><div className="metric-detail-list"><div className="metric-detail-toolbar"><button type="button" onClick={() => setShowMetricCubeNets((value) => !value)} className="metric-toolbar-button">{showMetricCubeNets ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}{showMetricCubeNets ? (vi ? "ẨN CUBENET" : "HIDE CUBENET") : (vi ? "HIỆN CUBENET" : "SHOW CUBENET")}</button>{selectedMetric === "ao5" && selectedMetricDetail && <button type="button" onClick={() => exportAo5Image(selectedMetricDetail.entries, selectedMetricDetail.exclusions, selectedMetricDetail.value, vi)} className="metric-toolbar-button metric-toolbar-button--primary"><ImageDown className="h-3.5 w-3.5" />{vi ? "XUẤT ẢNH AO5" : "EXPORT AO5 PNG"}</button>}</div><p className="metric-detail-kicker">{vi ? "SCRAMBLE CẤU THÀNH" : "CONTRIBUTING SCRAMBLES"} · {selectedMetricDetail?.entries.length ?? 0} {vi ? "LƯỢT" : "SOLVES"}</p>{selectedMetric?.startsWith("ao") && <p className="metric-exclusion-legend"><span>{vi ? "BEST · LOẠI" : "BEST · DISCARDED"}</span><span>{vi ? "WORST · LOẠI" : "WORST · DISCARDED"}</span></p>}{selectedMetricDetail?.entries.map((entry) => <MetricDetailCard key={entry.id} entry={entry} exclusion={selectedMetricDetail.exclusions[entry.id]} vi={vi} showCubeNet={showMetricCubeNets} copied={copiedScrambleId === entry.id} onCopy={copyMetricScramble} onExpand={setExpandedMetricCube} onReplay={openScrambleReplay} />)}{selectedMetricDetail && !selectedMetricDetail.entries.length && <p className="border-2 border-dashed border-[#17221d]/20 p-4 font-mono text-xs text-[#17221d]/55">{vi ? "Chưa có scramble để hiển thị." : "No scrambles are available for this metric."}</p>}</div><DialogFooter><button onClick={() => setSelectedMetric(null)} className="scanner-button scanner-secondary">{copy.close}</button></DialogFooter></DialogContent></Dialog>
    <Dialog open={Boolean(expandedMetricCube)} onOpenChange={(open) => !open && setExpandedMetricCube(null)}><DialogContent className="metric-cube-zoom-dialog border-2 border-[#17221d] bg-[#f4f0e8] text-[#17221d]"><DialogHeader><DialogTitle className="font-mono text-sm tracking-[0.14em]">{vi ? "CUBENET · SCRAMBLE" : "CUBENET · SCRAMBLE"}</DialogTitle><DialogDescription className="formula-content break-words font-mono text-xs">{expandedMetricCube?.input}</DialogDescription></DialogHeader>{expandedMetricCube && <div className="metric-cube-zoom-stage"><CubeNet state={safeScrambleState(expandedMetricCube.input)} /></div>}<DialogFooter><button onClick={() => setExpandedMetricCube(null)} className="scanner-button scanner-secondary">{copy.close}</button></DialogFooter></DialogContent></Dialog>
    <Dialog open={Boolean(editing)} onOpenChange={(open) => !open && setEditing(null)}><DialogContent className="max-h-[90vh] overflow-y-auto border-2 border-[#17221d] bg-[#f4f0e8] text-[#17221d]"><DialogHeader><DialogTitle>{copy.edit}</DialogTitle><DialogDescription>{editing?.input}</DialogDescription></DialogHeader><label className="font-mono text-[10px] font-bold tracking-[0.14em]">{copy.base}<input type="number" min="0" step="0.01" value={editSeconds} onChange={(event) => setEditSeconds(event.target.value)} className="mt-2 w-full rounded-sm border-2 border-[#17221d]/20 bg-white p-3 font-mono text-base" /></label><label className="font-mono text-[10px] font-bold tracking-[0.14em]">{copy.penalty}<select value={editPenalty} onChange={(event) => setEditPenalty(event.target.value as SolvePenalty)} className="mt-2 w-full rounded-sm border-2 border-[#17221d]/20 bg-white p-3 font-mono text-base"><option value="none">{copy.none}</option><option value="+2">{copy.plusTwo}</option><option value="DNF">{copy.dnf}</option></select></label><MoveComposer value={editSolution} onChange={(value) => { setEditSolution(value); if (solutionError) setSolutionError(""); }} label={copy.solution} pasteLabel={copy.solutionHint} />{solutionError && <p role="alert" className="border-2 border-[#d95743]/45 bg-[#d95743]/10 p-3 font-mono text-[10px] leading-5 text-[#8b2d21]">{solutionError}</p>}<label className="font-mono text-[10px] font-bold tracking-[0.14em]">{copy.note}<textarea value={editNote} onChange={(event) => setEditNote(event.target.value)} className="mt-2 min-h-20 w-full resize-none rounded-sm border-2 border-[#17221d]/20 bg-white p-3 text-sm" /></label><label className="font-mono text-[10px] font-bold tracking-[0.14em]">{copy.tags}<input value={editTags} onChange={(event) => setEditTags(event.target.value)} className="mt-2 w-full rounded-sm border-2 border-[#17221d]/20 bg-white p-3 font-mono text-sm" /></label><DialogFooter><button onClick={() => setEditing(null)} className="scanner-button scanner-secondary">{copy.cancel}</button><button onClick={saveEdit} className="scanner-button">{copy.save}</button></DialogFooter></DialogContent></Dialog>

    <Dialog open={Boolean(replay)} onOpenChange={(open) => { if (!open) { setReplay(null); setReplayPlaying(false); setReplayStep(0); setReplayMode("solution"); } }}><DialogContent className="max-h-[90vh] max-w-3xl overflow-y-auto border-2 border-[#17221d] bg-[#f4f0e8] text-[#17221d]"><DialogHeader><DialogTitle>{replayMode === "scramble" ? (vi ? "PHÁT LẠI SCRAMBLE" : "SCRAMBLE REPLAY") : copy.playbackTitle}</DialogTitle><DialogDescription>{replayText}</DialogDescription></DialogHeader>{replayTrace.length ? <div className="grid gap-5 md:grid-cols-[minmax(0,1fr)_240px]"><Cube3DGuide state={replayCurrent} previousState={replayPrevious} move={replayStep ? replayTrace[replayStep - 1]?.move : undefined} step={replayStep} crossColor={inspectionColor} alignCross /><div className="flex flex-col justify-between rounded-sm border-2 border-[#17221d] bg-white p-4"><div><p className="font-mono text-[10px] font-bold tracking-[0.14em] text-[#1ba77a]">{copy.move}</p><p className="mt-2 font-mono text-4xl font-black">{replayStep ? replayTrace[replayStep - 1]?.move : "—"}</p><p className="mt-3 font-mono text-xs text-[#17221d]/60">{replayStep} / {replayTrace.length}{replayMode === "solution" ? ` · ${copy.tps} ${replayTps.toFixed(2)}` : ""}</p><label className="mt-5 block font-mono text-[10px] font-bold tracking-[0.12em]">{copy.speed} {replaySpeed.toFixed(2)}×<input type="range" min="0.5" max="2" step="0.25" value={replaySpeed} onChange={(event) => setReplaySpeed(Number(event.target.value))} className="mt-2 w-full accent-[#1ba77a]" /></label>{replayMode === "solution" && replay?.phaseSplits.length ? <div className="mt-5 border-y border-[#17221d]/10 py-3"><p className="font-mono text-[10px] font-bold tracking-[0.12em] text-[#1ba77a]">{copy.splitTimes}</p><div className="mt-2 grid grid-cols-2 gap-x-3 gap-y-1">{replay.phaseSplits.map((split) => <p key={split.phase} className="font-mono text-[10px]"><b>{split.phase}</b> <span className="text-[#17221d]/60">{(split.elapsedMs / 1000).toFixed(2)}s</span></p>)}</div></div> : null}{replayMode === "solution" && phaseTps.length ? <div className="mt-5"><p className="font-mono text-[10px] font-bold tracking-[0.12em] text-[#1ba77a]">{copy.tpsByPhase}</p><div className="mt-2 h-28"><ResponsiveContainer width="100%" height="100%"><BarChart data={phaseTps}><XAxis dataKey="phase" axisLine={false} tickLine={false} tick={{ fontSize: 9 }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 9 }} width={24} /><Tooltip formatter={(value) => [`${Number(value).toFixed(2)} TPS`, copy.tps]} /><Bar dataKey="tps" fill="#1ba77a" radius={[2, 2, 0, 0]} /></BarChart></ResponsiveContainer></div></div> : replayMode === "solution" ? <p className="mt-5 font-mono text-[9px] leading-4 text-[#17221d]/55">{copy.tpsEmpty}</p> : null}</div><div className="mt-6 flex flex-wrap gap-2"><button onClick={() => setReplayStep((value) => Math.max(0, value - 1))} className="scanner-button scanner-secondary">←</button><button onClick={() => setReplayPlaying((value) => !value)} className="scanner-button flex-1">{replayPlaying ? <Pause className="h-4 w-4 fill-current" /> : <Play className="h-4 w-4 fill-current" />}{replayPlaying ? "Pause" : "Play"}</button><button onClick={() => setReplayStep((value) => Math.min(replayTrace.length, value + 1))} className="scanner-button scanner-secondary">→</button><button onClick={() => { setReplayStep(0); setReplayPlaying(false); }} className="scanner-button scanner-secondary w-full"><RotateCcw className="h-4 w-4" />{copy.restart}</button></div></div></div> : <p className="border-2 border-dashed border-[#17221d]/20 bg-white p-4 text-sm text-[#17221d]/60">{copy.noSolution}</p>}<DialogFooter><button onClick={() => setReplay(null)} className="scanner-button scanner-secondary">{copy.close}</button></DialogFooter></DialogContent></Dialog>

    <AlertDialog open={Boolean(deleteTarget)} onOpenChange={(open) => !open && setDeleteTarget(null)}><AlertDialogContent className="border-2 border-[#17221d] bg-[#f4f0e8] text-[#17221d]"><AlertDialogHeader><AlertDialogTitle>{copy.deleteTitle}</AlertDialogTitle><AlertDialogDescription>{copy.deleteDetail}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>{copy.cancel}</AlertDialogCancel><AlertDialogAction onClick={() => { if (deleteTarget) setEntries(deleteSolveHistory(deleteTarget.id)); setDeleteTarget(null); }} className="bg-[#d95743] text-white hover:bg-[#bb4533]">{copy.remove}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={bulkDeleteOpen} onOpenChange={setBulkDeleteOpen}><AlertDialogContent className="border-2 border-[#17221d] bg-[#f4f0e8] text-[#17221d]"><AlertDialogHeader><AlertDialogTitle>{copy.deleteManyTitle}</AlertDialogTitle><AlertDialogDescription>{copy.deleteManyDetail}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>{copy.cancel}</AlertDialogCancel><AlertDialogAction onClick={deleteSelected} className="bg-[#d95743] text-white hover:bg-[#bb4533]">{copy.deleteSelected}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    </>}
  </div></main>;
}

function Metric({ label, value }: { label: string; value: string }) { return <div className="border-2 border-[#17221d] bg-white p-3"><p className="font-mono text-[9px] text-[#17221d]/50">{label}</p><b className="mt-1 block font-mono text-lg tracking-[-0.06em]">{value}</b></div>; }
function MetricDetailCard({ entry, exclusion, vi, showCubeNet, copied, onCopy, onExpand, onReplay }: { entry: SolveHistoryEntry; exclusion?: "best" | "worst"; vi: boolean; showCubeNet: boolean; copied: boolean; onCopy: (entry: SolveHistoryEntry) => void; onExpand: (entry: SolveHistoryEntry) => void; onReplay: (entry: SolveHistoryEntry) => void }) { const state = useMemo(() => safeScrambleState(entry.input), [entry.input]); const solution = useMemo(() => validateRecordedSolution(initialStateFor(entry), entry.solution), [entry]); const canReplay = solution.valid && solution.moves.length > 0; return <article className={`metric-detail-row${!showCubeNet ? " metric-detail-row--no-cube" : ""}${exclusion ? ` metric-detail-row--${exclusion}` : ""}`}>{showCubeNet && <button type="button" onClick={() => onExpand(entry)} className="metric-scramble-cube" title={vi ? "Phóng to CubeNet" : "Enlarge CubeNet"}><CubeNet state={state} compact /><span><Maximize2 className="h-3.5 w-3.5" /></span></button>}<div className="min-w-0"><div className="flex flex-wrap items-start justify-between gap-2"><span className="font-mono text-[10px] text-[#17221d]/55">{new Date(entry.createdAt).toLocaleString(vi ? "vi-VN" : "en-US")}</span><div className="flex items-center gap-2"><b className={`font-mono text-sm ${entry.penalty === "DNF" ? "text-[#b23b2b]" : ""}`}>{formatSolveResult(entry)}</b>{exclusion && <span className={`metric-exclusion-tag metric-exclusion-tag--${exclusion}`}>{exclusion === "best" ? (vi ? "BEST · LOẠI" : "BEST · DISCARDED") : (vi ? "WORST · LOẠI" : "WORST · DISCARDED")}</span>}</div></div><p className="formula-content mt-2 break-words border-l-2 border-[#1ba77a] pl-3 font-mono text-sm font-bold leading-6">{entry.input}</p><div className="mt-3 flex flex-wrap items-center gap-2"><button type="button" onClick={() => onCopy(entry)} className="metric-scramble-copy"><ClipboardCheck className="h-3.5 w-3.5" />{copied ? (vi ? "ĐÃ CHÉP" : "COPIED") : (vi ? "SAO CHÉP" : "COPY")}</button>{canReplay ? <button type="button" onClick={() => onReplay(entry)} className="metric-scramble-copy" title={vi ? "Phát lại solution thực tế đã lưu" : "Replay the saved solution"}><Play className="h-3.5 w-3.5 fill-current" />{vi ? "PHÁT SOLUTION" : "PLAY SOLUTION"}</button> : <span className="font-mono text-[9px] font-bold tracking-[0.08em] text-[#17221d]/45">{vi ? "CHƯA LƯU SOLUTION" : "NO SAVED SOLUTION"}</span>}</div></div></article>; }
function MetricButton({ label, value, enabled, onClick }: { label: string; value: string; enabled: boolean; onClick: () => void }) { return <button type="button" disabled={!enabled} onClick={onClick} className="metric-drilldown border-2 border-[#17221d] bg-white p-3 text-left disabled:cursor-default disabled:opacity-65"><p className="font-mono text-[9px] text-[#17221d]/50">{label}</p><b className="mt-1 block font-mono text-lg tracking-[-0.06em]">{value}</b></button>; }
function MetricDark({ label, value }: { label: string; value: string }) { return <div className="border border-white/20 bg-white/5 p-3"><p className="font-mono text-[9px] text-[#f4f0e8]/50">{label}</p><b className="mt-1 block font-mono text-lg tracking-[-0.06em] text-[#1ba77a]">{value}</b></div>; }
